  foreach((string Name,string Definition) missing in new[]{("ProductionRepresentationHash","TEXT NULL"),("ResultBusinessJson","TEXT NULL"),("ActivationStatus","TEXT NOT NULL DEFAULT 'Pending'"),("ActivationAttemptCount","INTEGER NOT NULL DEFAULT 0"),("ActivatedUtc","TEXT NULL"),("ActivationDiagnostic","TEXT NULL"),("ReconciliationAttemptCount","INTEGER NOT NULL DEFAULT 0"),("LastReconciledUtc","TEXT NULL"),("ReconciliationDiagnostic","TEXT NULL")})if(!columns.Contains(missing.Name)){await using var alter=c.CreateCommand();alter.CommandText=$"ALTER TABLE PublicationOperationStates ADD COLUMN {missing.Name} {missing.Definition};";await alter.ExecuteNonQueryAsync(ct);}
  columns.Clear();await using(var inspect=c.CreateCommand()){inspect.CommandText="SELECT name FROM pragma_table_info('PublicationStates');";await using var reader=await inspect.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))columns.Add(reader.GetString(0));}
  foreach((string Name,string Definition) missing in new[]{("FinalManifestJson","TEXT NULL"),("FinalManifestHash","TEXT NULL"),("PublicProductionHash","TEXT NULL"),("PreparedReceiptJson","TEXT NULL"),("PreparedReceiptHash","TEXT NULL"),("FinalReceiptJson","TEXT NULL"),("FinalReceiptHash","TEXT NULL")})if(!columns.Contains(missing.Name)){await using var alter=c.CreateCommand();alter.CommandText=$"ALTER TABLE PublicationStates ADD COLUMN {missing.Name} {missing.Definition};";await alter.ExecuteNonQueryAsync(ct);}
  await MigrateLegacyTrajectoryReadRoutesAsync(c,ct);
 }
 async Task MigrateLegacyTrajectoryReadRoutesAsync(SqliteConnection c,CancellationToken ct)
 {
  await using var tx=c.BeginTransaction(false);var affected=new List<(string OperationId,string ScenarioId)>();await using(var select=Command(c,tx,"""
   SELECT o.OperationId,p.ScenarioId FROM PublicationOperations o
   JOIN PublicationOperationStates s ON s.OperationId=o.OperationId
   JOIN PublicationPlans p ON p.PublicationPlanId=o.PublicationPlanId
   WHERE o.RecordKind='Trajectory' AND s.Status<>'Verified' AND instr(o.ReadRoute,'?')=0
   ORDER BY p.ScenarioId,o.Sequence;
   """)){await using var reader=await select.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))affected.Add((reader.GetString(0),reader.GetString(1)));}
  if(affected.Count!=0){await using(var migrate=Command(c,tx,"""
   DROP TRIGGER IF EXISTS TR_PublicationOperations_NoUpdate;
   UPDATE PublicationOperations SET ReadRoute=ReadRoute||'?includeCalculatedStations=true'
   WHERE RecordKind='Trajectory' AND instr(ReadRoute,'?')=0
     AND EXISTS(SELECT 1 FROM PublicationOperationStates s WHERE s.OperationId=PublicationOperations.OperationId AND s.Status<>'Verified');
   CREATE TRIGGER TR_PublicationOperations_NoUpdate BEFORE UPDATE ON PublicationOperations BEGIN SELECT RAISE(ABORT,'Publication operations are immutable');END;
   """)){await migrate.ExecuteNonQueryAsync(ct);}foreach(var item in affected)await AppendAuditAsync(c,tx,item.ScenarioId,"publication.trajectory-read-route-migrated",item.OperationId,CanonicalJson.Serialize(new{readRouteQuery="includeCalculatedStations=true"}),ct);}
  await tx.CommitAsync(ct);
 }
