 const string PublicationSchema="""
 CREATE TABLE IF NOT EXISTS PublicationPlans(PublicationPlanId TEXT PRIMARY KEY,RunId TEXT NOT NULL UNIQUE,ScenarioId TEXT NOT NULL,RevealId TEXT NOT NULL UNIQUE,ClonedFieldId TEXT NOT NULL,ObservationModelVersion TEXT NOT NULL,ValidTimeUtc TEXT NOT NULL,ManifestJson TEXT NOT NULL,ManifestHash TEXT NOT NULL,OperationCount INTEGER NOT NULL,CreatedUtc TEXT NOT NULL,FOREIGN KEY(RunId)REFERENCES Runs(RunId));
 CREATE TABLE IF NOT EXISTS PublicationOperations(OperationId TEXT PRIMARY KEY,PublicationPlanId TEXT NOT NULL,Sequence INTEGER NOT NULL,TargetService TEXT NOT NULL,Route TEXT NOT NULL,ReadRoute TEXT NOT NULL,EntityId TEXT NOT NULL,RecordKind TEXT NOT NULL,CanonicalPayloadJson TEXT NOT NULL,PayloadHash TEXT NOT NULL,UNIQUE(PublicationPlanId,Sequence),FOREIGN KEY(PublicationPlanId)REFERENCES PublicationPlans(PublicationPlanId));
 CREATE TABLE IF NOT EXISTS PublicationOperationStates(OperationId TEXT PRIMARY KEY,Status TEXT NOT NULL,AttemptCount INTEGER NOT NULL,ResultHash TEXT NULL,VerifiedUtc TEXT NULL,Diagnostic TEXT NULL,ProductionRepresentationHash TEXT NULL,ResultBusinessJson TEXT NULL,ActivationStatus TEXT NOT NULL DEFAULT 'Pending',ActivationAttemptCount INTEGER NOT NULL DEFAULT 0,ActivatedUtc TEXT NULL,ActivationDiagnostic TEXT NULL,ReconciliationAttemptCount INTEGER NOT NULL DEFAULT 0,LastReconciledUtc TEXT NULL,ReconciliationDiagnostic TEXT NULL,FOREIGN KEY(OperationId)REFERENCES PublicationOperations(OperationId));
 CREATE TABLE IF NOT EXISTS PublicationStates(PublicationPlanId TEXT PRIMARY KEY,Status TEXT NOT NULL,AttemptCount INTEGER NOT NULL,VerifiedOperationCount INTEGER NOT NULL,ReceiptJson TEXT NULL,ReceiptHash TEXT NULL,Diagnostic TEXT NULL,UpdatedUtc TEXT NOT NULL,FinalManifestJson TEXT NULL,FinalManifestHash TEXT NULL,PublicProductionHash TEXT NULL,PreparedReceiptJson TEXT NULL,PreparedReceiptHash TEXT NULL,FinalReceiptJson TEXT NULL,FinalReceiptHash TEXT NULL,FOREIGN KEY(PublicationPlanId)REFERENCES PublicationPlans(PublicationPlanId));
 CREATE TRIGGER IF NOT EXISTS TR_PublicationPlans_NoUpdate BEFORE UPDATE ON PublicationPlans BEGIN SELECT RAISE(ABORT,'Publication plans are immutable');END;CREATE TRIGGER IF NOT EXISTS TR_PublicationPlans_NoDelete BEFORE DELETE ON PublicationPlans BEGIN SELECT RAISE(ABORT,'Publication plans are immutable');END;
 CREATE TRIGGER IF NOT EXISTS TR_PublicationOperations_NoUpdate BEFORE UPDATE ON PublicationOperations BEGIN SELECT RAISE(ABORT,'Publication operations are immutable');END;CREATE TRIGGER IF NOT EXISTS TR_PublicationOperations_NoDelete BEFORE DELETE ON PublicationOperations BEGIN SELECT RAISE(ABORT,'Publication operations are immutable');END;
 """;
}

public sealed class PublicationCoordinator(DrillingOperationsStore store,AnalysisVerificationClient verification,AnalysisPublicationClient packages,AnalysisRevealClient reveal,OntologyPublicationClient ontology)
{
 public async Task<ApiOutcome> PublishAsync(string route,string key,string runId,CancellationToken ct)
 {
  await PublicationRecoveryCoordinator.PublicationMutationGate.WaitAsync(ct);
  try{return await PublishCoreAsync(route,key,runId,ct);}
  finally{PublicationRecoveryCoordinator.PublicationMutationGate.Release();}
 }
