   if(plan is null){AnalysisPackageDocument source=await packages.GetPackageAsync(authoritativeScenario.SourceFieldId,ct);var artifacts=new PublicationArtifactSet((await store.GetBindingAsync(run.ScenarioId,ct))!,(await store.GetMaterializedPlanAsync(runId,ct))!,(await store.GetDrillingExecutionAsync(runId,ct))!,(await store.GetSurveyArtifactAsync(runId,ct))!,(await store.GetLogObservationBatchAsync(runId,ct))!,(await store.GetCompletionDesignAsync(runId,ct))!,(await store.GetProductionSeriesAsync(runId,ct))!,authoritativeScenario);plan=await store.StagePublicationAsync(DeterministicPublicationPlanner.Create(source,artifacts),ct);}
