   {
    foreach(var op in await store.GetIncompletePublicationOperationsAsync(runId,ct)){await EnsureNotCancelled();try{PublicationWriteReceipt result=await ontology.WriteAndVerifyAsync(op,plan.ScenarioId,plan.RevealId,plan.ProductionEntityId,ct);await store.MarkPublicationOperationVerifiedAsync(op.OperationId,result,ct);}catch(PublicationUpstreamException e){await store.MarkPublicationOperationAttemptFailedAsync(op.OperationId,e.DiagnosticCode,e.StatusCode is 502 or 503||e.DiagnosticCode is "PublicationReadAfterWriteMismatch",ct);throw;}}
